solution.solution.py:
def transistors(year):
    return round(2300 * 2 ** ((year - 1971) / 2))

def year_reaching(count):
    year = 1971
    while transistors(year) < count:
        year += 1
    return year

unitTests:
@test("doubling every two years")
def _():
    check_eq(transistors(1971), 2300)
    check_eq(transistors(1973), 4600)
    check_eq(transistors(1981), 73600)
    check_eq(transistors(1972), 3253)

@test("when a count is reached")
def _():
    check_eq(year_reaching(2300), 1971)
    check_eq(year_reaching(10_000), 1976)
    check_eq(year_reaching(1_000_000_000), 2009)

